  const txt = h.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
  const vis = [...txt.matchAll(/(?:\+?55[\s.-]?)?\(?\b([1-9]{2})\)?[\s.-]?(9[\s.-]?\d{4}|[2-5]\d{3})[\s.-]?(\d{4})\b/g)].map(m => normBR(m[1] + m[2] + m[3]));
